@GetMapping("/authorities")
@ResponseBody
public String authorities(Authentication auth) {
    for (GrantedAuthority a : auth.getAuthorities()) {
        System.out.println(">>> " + a.getClass().getSimpleName()
                + " : " + a.getAuthority());
    }
    return auth.getAuthorities().toString();
}

